docs.usage:
import * as ComboBox from "@/components/ui/combo-box"

// Simple usage
<ComboBox.Composed
  options={options}
  value={selected}
  onValueChange={setSelected}
/>

// Compound usage
<ComboBox.Root options={options} value={selected} onValueChange={setSelected}>
  <ComboBox.SearchTrigger />
  <ComboBox.Content />
  <ComboBox.Tags />
</ComboBox.Root>
